<script setup lang="ts">import { onMounted,ref,computed } from 'vue';import http from '../api/http';const pending=ref(0);const stats=ref<Record<string,number>>({});const loading=ref(true);const cards=computed(()=>[{label:'待我处理审批',value:pending.value,trend:'需要及时处理',tone:'blue'},{label:'已发布物料',value:stats.value.published||0,trend:'可被业务系统引用',tone:'green'},{label:'主数据审批中',value:stats.value.pending||0,trend:'等待流程推进',tone:'orange'},{label:'主数据草稿',value:stats.value.draft||0,trend:'尚未提交发布',tone:'purple'}]);onMounted(async()=>{try{const[a,m]=await Promise.all([http.get('/workflow/tasks/pending/count'),http.get('/mdm/materials/stats')]);pending.value=a.data.data;stats.value=m.data.data}finally{loading.value=false}})</script>
<template><section v-loading="loading"><div class="hero"><div><h1 class="page-title">经营驾驶舱</h1><p class="page-subtitle">实时掌握从主数据、订单到制造执行的关键协同状态</p></div><div class="date-badge"><b>实时演示环境</b><span>数据状态每次操作即时更新</span></div></div><el-row :gutter="16" class="section-gap"><el-col v-for="c in cards" :key="c.label" :span="6"><el-card class="metric-card" :class="c.tone"><div class="metric-label">{{c.label}}</div><div class="metric-value">{{c.value}}</div><div class="metric-note">{{c.trend}}</div></el-card></el-col></el-row><el-row :gutter="16" class="section-gap"><el-col :span="15"><el-card class="flow-card"><template #header><div class="card-header"><b>端到端制造业务链路</b><span>数据与流程的实时协同</span></div></template><div class="flow"><div class="flow-step active"><b>01</b><span>主数据</span><small>物料 · BOM</small></div><i>→</i><div class="flow-step"><b>02</b><span>订单需求</span><small>商机 · 销售订单</small></div><i>→</i><div class="flow-step"><b>03</b><span>生产计划</span><small>生产订单</small></div><i>→</i><div class="flow-step"><b>04</b><span>制造执行</span><small>工单 · 报工 · 质量</small></div><i>→</i><div class="flow-step"><b>05</b><span>运营分析</span><small>成本 · 能源 · AI</small></div></div></el-card></el-col><el-col :span="9"><el-card class="risk-card"><template #header><div class="card-header"><b>今日关注</b><span>业务风险提示</span></div></template><div class="risk-item"><span class="risk-dot warning"></span><div><b>审批待办</b><p>{{pending}} 条待办等待当前身份处理</p></div></div><div class="risk-item"><span class="risk-dot success"></span><div><b>主数据治理</b><p>{{stats.published||0}} 条物料已发布并可分发使用</p></div></div><div class="risk-item"><span class="risk-dot info"></span><div><b>数据闭环</b><p>业务单据将持续沉淀至数仓与 AI 分析层</p></div></div></el-card></el-col></el-row></section></template><style scoped>.hero{display:flex;justify-content:space-between;align-items:center}.date-badge{padding:10px 15px;border-radius:10px;background:#ecf5ff;color:#3269ad;font-size:12px}.date-badge b,.date-badge span{display:block}.date-badge span{margin-top:3px;color:#6a8eb9}.metric-note{margin-top:8px;font-size:12px;color:#8c9bb0}.green .metric-value{color:#129a74}.orange .metric-value{color:#e38527}.purple .metric-value{color:#7959c5}.card-header{display:flex;justify-content:space-between}.card-header span{font-size:12px;color:#91a0b4}.flow{display:flex;align-items:center;justify-content:space-between;padding:13px 4px}.flow>i{font-size:19px;font-style:normal;color:#b8c8da}.flow-step{display:flex;flex-direction:column;gap:4px;align-items:center;min-width:86px;text-align:center;color:#7587a0}.flow-step b{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#edf2f8;color:#7390b2}.flow-step span{font-weight:700;color:#36516f;font-size:13px}.flow-step small{font-size:11px}.flow-step.active b{background:#2d7fea;color:#fff}.risk-item{display:flex;gap:10px;padding:11px 0;border-bottom:1px solid #eff2f6}.risk-item:last-child{border:0}.risk-dot{margin-top:5px;width:9px;height:9px;border-radius:50%;background:#6095dd}.risk-dot.warning{background:#efa33a}.risk-dot.success{background:#32b481}.risk-item b{font-size:13px;color:#36516f}.risk-item p{margin-top:4px;color:#8797ab;font-size:12px}</style>
